function definition(name){
	return basic_stats[name].split(": ")[1];
}


function translate_hp(hp, mode = 0){
	if (!isNaN(hp - parseFloat(hp))){
		if (mode == 0){
			return hp*100 + "%";
		}else{
			hp = hp*1000;
			let res = "";
			if (hp % 1000 == 0){
				res = hp/1000 + " lethal";
			}else if (hp%500 == 0){
				res = hp/500 + " severe";
			}else if (hp%250 == 0){
				res = hp/250 + " moderate";
			}else if (hp%125 == 0){
				res = hp/125 + " minor";
			}else{
				res = hp;
			}
			if (mode == 2){
				if (res.slice(0, 2) == "1 "){
					res += " wound";
				}else{
					res += " wounds"
				}
			}
			return res;
			
		}
	}else{
		return hp;
	}
	
}

function sorting_by_param(arr, param = "name", order = (1 == 1)){
	let par_list = Array();
	
	for (var el of arr){
		if (!par_list.includes(el[param])){
			par_list.push(el[param]);
		}
	}
	
	par_list.sort();
	
	if (order){
		par_list.reverse();
	}
	let copy_arr = Array();
	
	for (var p of par_list){
		for (var el of arr){
			if (par_list.includes(el[param])){
				if (el[param] == p){
					copy_arr.push(el);
				}
			}
		}
	}
	
	return copy_arr;
}

function filtering_by_param(arr, param, value, mode = 1){
	let copy_arr = Array();
	if (value.length == 0){
		return arr;
	}
	for (var el of arr){
		if (Object.keys(el).includes(param)){
			if (mode == 1){
				if (value.every( (v) => el[param].includes(v) ) ){
					copy_arr.push(el);
				}
			}else{
				if (value.some( (v) => el[param].includes(v) ) ){
					copy_arr.push(el);
				}
			}
		}
	}
	return copy_arr;
}

function similar(arr, param){
	let test = arr[0];
	let count = 0;
	for (var el of arr){
		if (!(el[param] === test[param])){
			count = 1;
		}else{
//			console.log(test[param]);
//			console.log(el[param]);
		}
	}
	return count;
}